curl -s https://opencode.ai/config.json > /tmp/opencode/config-schema.json && python3 - <<'EOF'
import json
s=json.load(open('/tmp/opencode/config-schema.json'))
# find permission definitions
def find(obj, path=""):
    if isinstance(obj, dict):
        for k,v in obj.items():
            if k=="permission" or (isinstance(k,str) and "permission" in k.lower()):
                print("FOUND at", path+"/"+k)
                print(json.dumps(v, indent=2)[:5000])
                print("---")
            find(v, path+"/"+k)
    elif isinstance(obj, list):
        for i,v in enumerate(obj):
            find(v, path+f"[{i}]")
find(s)
print("top-level keys:", list(s.get("properties",{}).keys()))
EOF

