    failed: usize,
    touched_selected: bool,
    refresh_grid_when_done: bool,
    on_finished: Option<Box<dyn Fn()>>,
}

fn start_bulk_recipe_update(context: &PhotoActionContext, plan: BulkRecipePlan, ids: Vec<i64>, refresh_grid_when_done: bool) {
    if ids.is_empty() { return; }
    let name = match plan { ... };
    context.operation_progress.begin(name, ids.len());
    let state = Rc::new(RefCell::new(Some(BulkRecipeState { ... })));
    glib::timeout_add_local(Duration::from_millis(0), move || {
        let Some(mut work) = state.borrow_mut().take() else { return glib::ControlFlow::Break; };
        // process one chunk
        ...
        if work.index >= work.ids.len() {
            // finish
            finish_bulk(work);
            glib::ControlFlow::Break
        } else {
            *state.borrow_mut() = Some(work);
            glib::ControlFlow::Continue
        }
    });
}
```

Using Option to take state each tick avoids borrow issues. timeout 0ms = idle-ish but yields to UI between chunks. Actually `glib::timeout_add_local(Duration::from_millis(1), ...)` between chunks to let events process. First call delay 0.

