    Ok(Photo {
        id: row.get(0)?,
        path: row.get(1)?,
        folder_id: row.get(2)?,
        taken_at: row.get(3)?,
        camera: row.get(4)?,
        width: row.get(5)?,
        height: row.get(6)?,
        size_bytes: row.get(7)?,
        mtime: row.get(8)?,
        added_at: row.get(9)?,
        rotation: row.get(10)?,
        edit_recipe: row.get(11)?,
        favorite: row.get(12)?,
        trashed: row.get(13)?,
        folder_path: row.get(14)?,
    })
}

