import gi
gi.require_version('Atspi', '2.0')
from gi.repository import Atspi
Atspi.init()
desktop = Atspi.get_desktop(0)
app = None
for i in range(desktop.get_child_count()):
    a = desktop.get_child_at_index(i)
    if a and (a.get_name() or '') == 'pic-rs':
        app = a
        break
print('app', app)
interesting_roles = {
 'push button','toggle button','menu','menu item','radio button','check box',
 'entry','text','combo box','table','dialog','frame','link','page tab list','page tab',
 'tool bar','panel','status bar','label','separator'
}
count = 0
def walk(node, depth=0, path=''):
    global count
    if depth > 10 or count > 400:
        return
    n = node.get_name() or ''
    r = node.get_role_name() or ''
    st = ''
    try:
        states = node.get_state_set()
        if states.contains(Atspi.StateType.VISIBLE): st += 'V'
        if states.contains(Atspi.StateType.SHOWING): st += 'S'
        if states.contains(Atspi.StateType.ENABLED): st += 'E'
        if states.contains(Atspi.StateType.SELECTED): st += 'Sel'
    except Exception:
        pass
    desc = ''
    try:
        d = node.get_description()
        if d: desc = f' desc={d!r}'
    except Exception:
        pass
    if r in interesting_roles or n:
        # filter empty panels a bit
        if r == 'panel' and not n:
            pass
        else:
            print(f'{"  "*depth}{r}: {n!r} [{st}]{desc}')
            count += 1
    # actions
    try:
        acts = node.get_action_iface()
        if acts:
            names = []
            for ai in range(acts.get_n_actions()):
                an = acts.get_action_name(ai)
                if an: names.append(an)
            if names and r in ('push button','toggle button','menu item','menu','link','table','page tab'):
                print(f'{"  "*depth}  actions={names}')
    except Exception:
        pass
    for c in range(node.get_child_count()):
        ch = node.get_child_at_index(c)
        if ch: walk(ch, depth+1)
walk(app)
print('TOTAL_PRINTED', count)
