import gi
gi.require_version('Atspi','2.0')
from gi.repository import Atspi
Atspi.init()
desktop = Atspi.get_desktop(0)
app = None
for i in range(desktop.get_child_count()):
    a = desktop.get_child_at_index(i)
    if a and a.get_name()=='pic-rs':
        app=a; break

# Collect actionable widgets with names/roles/paths
found = []
def walk(node, path=''):
    role = node.get_role_name() or ''
    name = node.get_name() or ''
    n = node.get_child_count()
    acts = []
    try:
        ai = node.get_action_iface()
        if ai:
            for j in range(ai.get_n_actions()):
                an = ai.get_action_name(j)
                if an: acts.append(an)
    except Exception:
        pass
    # always record buttons, menu items, tabs, entries
    if role in ('push button','toggle button','menu item','menu','page tab','entry','text','combo box','check box','radio button','table','dialog','frame','link','tool bar','status bar','label') or name or acts:
        if role != 'label' or name:
            found.append((path, role, name, acts, n, node))
    # limit depth exploration
    if n > 0 and len(path) < 80:
        for i in range(n):
            ch = node.get_child_at_index(i)
            if ch:
                walk(ch, path + f'/{i}:{role[:3]}')

walk(app)
print('FOUND', len(found))
for path, role, name, acts, n, node in found[:300]:
    extra = f' actions={acts}' if acts else ''
    print(f'{role}: {name!r}{extra} [{path}] children={n}')
print('---BUTTONS WITH ACTIONS---')
for path, role, name, acts, n, node in found:
    if role in ('push button','toggle button','menu item','page tab') and acts:
        print(role, repr(name), acts, path)
