           if desktop.get_child_at_index(i) and desktop.get_child_at_index(i).get_name()=='pic-rs')

def find(pred, node=None, depth=0):
    if node is None: node = app
    if depth>30: return None
    if pred(node): return node
    for i in range(node.get_child_count()):
        ch = node.get_child_at_index(i)
        if not ch: continue
        r = find(pred, ch, depth+1)
        if r: return r
    return None

def click(node, label=''):
    ai = node.get_action_iface()
    if not ai:
        print('NO ACTION', label or node.get_name())
        return False
    # prefer 'click'
    idx = 0
    for j in range(ai.get_n_actions()):
        if ai.get_action_name(j) == 'click':
            idx = j
            break
    ok = ai.do_action(idx)
    print(f'click {label or node.get_name()!r} -> {ok}')
    return ok

def find_btn(name, exact=True):
    if exact:
        return find(lambda n: n.get_role_name() in ('push button','toggle button') and (n.get_name() or '')==name)
    return find(lambda n: n.get_role_name() in ('push button','toggle button') and name in (n.get_name() or ''))

# 1. Switch to Text tab
text_tab = find_btn('Text')
print('Text tab', text_tab)
click(text_tab, 'Text tab')
time.sleep(0.6)

# 2. Find Add Text button (might be on Text panel now)
add = find_btn('Add Text')
if not add:
    add = find(lambda n: 'Add Text' in (n.get_name() or ''))
print('Add Text', add)
if add:
    click(add, 'Add Text')
    time.sleep(0.5)

# 3. Find text entry and set text via text interface or type
entry = find(lambda n: n.get_role_name() in ('entry','text') and (
    (n.get_name() or '') in ('', 'Your text') or 'text' in (n.get_name() or '').lower()
))
# broader: any entry that's not search
entries = []
def collect_entries(node, depth=0):
    if depth>30: return
    if node.get_role_name() in ('entry','text'):
        entries.append(node)
    for i in range(node.get_child_count()):
        ch=node.get_child_at_index(i)
        if ch: collect_entries(ch, depth+1)
collect_entries(app)
print('entries', [(e.get_role_name(), e.get_name(), e.get_child_count()) for e in entries])

# Also look for editable text with default "Your text"
texts = []
def collect_text(node, depth=0):
    if depth>30: return
    if node.get_role_name()=='text':
        texts.append(node)
    for i in range(node.get_child_count()):
        ch=node.get_child_at_index(i)
        if ch: collect_text(ch, depth+1)
collect_text(app)
print('text roles', [(t.get_name(), t.get_child_count()) for t in texts])

# Try Text interface on entries
from gi.repository import Atspi as A
for e in entries:
    try:
        ti = e.get_text_iface()
        if ti:
            print('entry text value:', repr(ti.get_text(0, 200)))
            print('attributes', ti.get_attributes() if hasattr(ti,'get_attributes') else None)
    except Exception as ex:
        print('text iface err', ex)

# Dump names around Text panel after clicking
def dump_textish(node, depth=0):
    if depth>25: return
    name=node.get_name() or ''
    role=node.get_role_name() or ''
    if any(k in name for k in ['Add','Text','Your','Delete','Bold','Font','Caption','type']) or role in ('entry','text'):
        acts=[]
        try:
            ai=node.get_action_iface()
            if ai:
                for j in range(ai.get_n_actions()):
                    acts.append(ai.get_action_name(j))
        except: pass
        print(f'{"  "*min(depth,10)}{role}: {name!r} act={acts}')
    for i in range(node.get_child_count()):
        ch=node.get_child_at_index(i)
        if ch: dump_textish(ch, depth+1)
print('--- text panel ---')
dump_textish(app)
print('DONE')
